import org.jetbrains.mps.openapi.model.SNode;
import jetbrains.mps.lang.smodel.generator.smodelAdapter.SModelOperations;
import jetbrains.mps.lang.smodel.generator.smodelAdapter.SNodeOperations;
import mpsUtils.MPSUtil;
import java.nio.file.Path;
import jetbrains.mps.internal.collections.runtime.Sequence;

public class PathUtil {
  public static String pathUptoGenDir(SNode node) {
    return SModelOperations.getModelName(SNodeOperations.getModel(SNodeOperations.getContainingRoot(node))).replaceAll("/", "_").replaceAll("\\.", "/").replaceAll("[^/]+", "..");
  }





  public static String sanitizePath(String... path) {
    if (path == null || path.length == 0) {
      return null;
    }
    final StringBuilder b = new StringBuilder();
    for (String part : Sequence.fromIterable(Sequence.fromArray(path)).where((it) -> (it != null && it.length() > 0))) {
      if (b.length() > 0) {
        b.append("/");
      }
      b.append(part.replaceAll("[:/\\\\<>|?!{}()*]+", "_"));
    }
    return b.toString();
  }

}
